22	
23	typedef struct {
24	    CommAbiHeader header;
25	    const uint32_t* rankIds; /* 用户希望填写的rankids */
26	    uint32_t rankNum;
27	    uint32_t selfRankId;
28	    uint32_t netLayer; /* 用户希望使用的网络层，0表示默认选择 */
29	    CommProtocol protocol; /* 用户希望使用的通信协议，-1表示保留协议类型, 1个team仅支持一个协议 */
30	    HcommTeamSyncMemRequirement requirement;
31	
32	    uint32_t reserved[4];
33	} HcclTeamCreateDesc;
34	
35	typedef struct {
36	    CommAbiHeader header;
37	    CommEngine engine;     /* COMM_ENGINE_AICPU_TS / CCU 等 */
38	    uint32_t notifyNum;    /* channel所需的notify数量 */
39	    CommProtocol protocol; /* 例如 COMM_PROTOCOL_HCCS / UBC_TP / UBOE */
40	    uint32_t channelCnt;   /*  用户可以自行指定channel个数 */
41	
42	    uint32_t reserved[4];
43	} HcclTeamCreateChannelsDesc;
44	
45	static const uint32_t HCCL_TEAM_CREATE_DESC_MAGIC_WORD = 0x0fcf0f14U;
46	static const uint32_t HCCL_TEAM_CREATE_DESC_VERSION = 1U;
47	
48	static const uint32_t HCCL_TEAM_CREATE_CHANNELS_DESC_MAGIC_WORD = 0x0fcf0f15U;
49	static const uint32_t HCCL_TEAM_CREATE_CHANNELS_DESC_VERSION = 1U;
50	
51	static inline HcclResult HcclTeamCreateDescInit(HcclTeamCreateDesc* desc)
52	{
53	    if (desc == NULL) {
54	        return HCCL_E_PTR;
55	    }
56	
57	    (void)memset_s(desc, sizeof(HcclTeamCreateDesc), 0xFF, sizeof(HcclTeamCreateDesc));
58	    desc->header.version = HCCL_TEAM_CREATE_DESC_VERSION;
59	    desc->header.magicWord = HCCL_TEAM_CREATE_DESC_MAGIC_WORD;
60	    desc->header.size = sizeof(HcclTeamCreateDesc);
61	    desc->header.reserved = 0;
62	    desc->rankIds = NULL;
63	    desc->rankNum = 0;
64	    desc->selfRankId = 0;
65	    desc->netLayer = 0;
66	    desc->protocol = COMM_PROTOCOL_RESERVED;
67	    desc->requirement.signalCount = 0;
68	    desc->requirement.counterCount = 0;
69	    desc->requirement.barrierCount = 0;
70	    for (uint32_t i = 0; i < 4; ++i) {
71	        desc->reserved[i] = 0;
72	    }
73	
74	    return HCCL_SUCCESS;
75	}
76	
77	static inline HcclResult HcclTeamCreateChannelsDescInit(HcclTeamCreateChannelsDesc* desc)
78	{
79	    if (desc == NULL) {
80	        return HCCL_E_PTR;
81	    }
82	
83	    (void)memset_s(desc, sizeof(HcclTeamCreateChannelsDesc), 0xFF, sizeof(HcclTeamCreateChannelsDesc));
84	    desc->header.version = HCCL_TEAM_CREATE_CHANNELS_DESC_VERSION;
85	    desc->header.magicWord = HCCL_TEAM_CREATE_CHANNELS_DESC_MAGIC_WORD;
86	    desc->header.size = sizeof(HcclTeamCreateChannelsDesc);
87	    desc->header.reserved = 0;
88	    desc->engine = COMM_ENGINE_RESERVED;
89	    desc->notifyNum = 0;
90	    desc->protocol = COMM_PROTOCOL_RESERVED;
91	    desc->channelCnt = 0;
92	    for (uint32_t i = 0; i < 4; ++i) {
93	        desc->reserved[i] = 0;
94	    }
95	
96	    return HCCL_SUCCESS;
97	}
98	
99	/**
100	 * @brief Create a world team for HCCL communication.
101	 *
102	 * @param comm A pointer identifying the initialized communication resource.
103	 * @param worldTeam A pointer identifying the created world team handle.
104	 * @return HcclResult
105	 * @see HcclTeamDestroy()
106	 */
107	extern HcclResult HcclWorldTeamCreate(HcclComm comm, const HcclTeamCreateDesc* desc, HcommTeamHandle* worldTeam);
108	
109	/**
110	 * @brief Create a sub team for HCCL communication.
111	 *
112	 * @param worldTeam A pointer identifying the world team handle.
113	 * @param desc A pointer identifying the sub team creation description.
114	 * @param team A pointer identifying the created sub team handle.
115	 * @return HcclResult
116	 * @see HcclTeamDestroy()
117	 */
118	extern HcclResult HcclSubTeamCreate(HcommTeamHandle worldTeam, const HcclTeamCreateDesc* desc, HcommTeamHandle* team);
119	
120	/**
121	 * @brief Destroy a team for HCCL communication.
122	 *
123	 * @param team A pointer identifying the team handle to be destroyed.
124	 * @return HcclResult
125	 * @see HcclWorldTeamCreate() / HcclSubTeamCreate()
126	 */
127	extern HcclResult HcclTeamDestroy(HcommTeamHandle team);
128	
129	/**
130	 * @brief Register a memory window for HCCL communication.
131	 *
132	 * @param comm A pointer identifying the communication resource based on.
133	 * @param team A pointer identifying the team handle.
134	 * @param localMem A pointer identifying the user memory address.
135	 * @param window A pointer identifying the registered memory window handle.
136	 * @param flag The flag of this memory window, now only support 0
137	 * @return HcclResult
138	 * @see HcclTeamWindowDeregister()
139	 */
140	/* 要保证所有team上的rank都调用, 只能给put接口用, 入参team仅能为worldTeam */
141	/* HcclTeamWindowRegister生成的windows必须要调用HcclTeamChannelsCreate之后才能生效，如果只创建不调用无法使用该windows */
142	extern HcclResult HcclTeamWindowRegister(
143	    HcclComm comm, HcommTeamHandle worldTeam, const CommMem* localMem, HcommWindowHandle* window, uint32_t flag);
144	
145	/**
146	 * @brief Deregister a memory window for HCCL communication.
147	 *
148	 * @param team A pointer identifying the team handle.
149	 * @param window A pointer identifying the registered memory window handle.
150	 * @return HcclResult
151	 * @see HcclTeamWindowRegister()
152	 */
153	extern HcclResult HcclTeamWindowDeregister(HcommTeamHandle worldTeam, HcommWindowHandle window);
154	
155	/**
156	 * @brief Create channels for a team for HCCL communication.
157	 *
158	 * @param   comm A pointer identifying the initialized communication resource.
159	 * @param   team A pointer identifying the team handle.
160	 * @param   desc A pointer identifying the team channel creation description.
161	 * @return  HcclResult
162	 */
163	extern HcclResult HcclTeamChannelsCreate(HcclComm comm, HcommTeamHandle team, const HcclTeamCreateChannelsDesc* desc);
164	#ifdef __cplusplus
165	}
166	#endif // __cplusplus
167	#endif // HCCL_TEAM_H
