25	#include "hcomm_result_defs.h"
26	#include "hcomm_team.h"
27	#include "hcomm_team_c_adpt.h"
28	#include "hcomm_team_mgr.h"
29	
30	using namespace hccl;
31	
32	/**
33	 * @note 职责：集合通信的通信域HcclTeam管理的C接口的C到C++适配
34	 */
35	
36	/* 在 rankIds 中查找 selfRankId 的下标作为 memberId。
37	 * 例如 rankIds=[1,3,5,7]，selfRankId=3，则 selfMemberId=1。未找到返回 HCCL_E_NOT_FOUND。 */
38	static HcclResult FindSelfMemberId(const HcclTeamCreateDesc* desc, uint32_t& selfMemberId)
39	{
40	    for (uint32_t i = 0; i < desc->rankNum; i++) {
41	        if (desc->rankIds[i] == desc->selfRankId) {
42	            selfMemberId = i;
43	            return HCCL_SUCCESS;
44	        }
45	    }
46	    HCCL_ERROR("[FindSelfMemberId] selfRankId[%u] not found in rankIds", desc->selfRankId);
47	    return HCCL_E_NOT_FOUND;
48	}
49	
50	/* 从 HcclTeamCreateDesc 填充 HcommTeamCreateDesc。
51	 * worldMemberIds：worldTeam 传 nullptr（L3 生成 [0,memberNum)）；subTeam 传 worldTeam 的 memberId 列表。 */
52	static void FillHcommTeamCreateDesc(
53	    const HcclTeamCreateDesc* desc, uint32_t selfMemberId, const uint32_t* worldMemberIds,
54	    HcommTeamCreateDesc& hcommDesc)
55	{
56	    /* 用头文件 Init 初始化 ABI 头部（magicWord/version/size）与默认字段，再覆盖业务字段。 */
57	    (void)HcommTeamCreateDescInit(&hcommDesc);
58	    hcommDesc.memberNum = desc->rankNum;
59	    hcommDesc.selfMemberId = selfMemberId;
60	    hcommDesc.worldMemberIds = worldMemberIds;
61	    hcommDesc.requirement.signalCount = 0;  // 不支持配置，强制为0
62	    hcommDesc.requirement.counterCount = 0; // 不支持配置，强制为0
63	    hcommDesc.requirement.barrierCount = desc->requirement.barrierCount;
64	    hcommDesc.netLayer = desc->netLayer;
65	    hcommDesc.protocol = desc->protocol;
66	}
67	
68	/* 反查 subTeam.rankIds 在 worldTeam.rankIds 中的下标作为 worldMemberIds（worldTeam 的 memberId）。
69	 * 用 unordered_map 预建 rankId→worldMemberId 反查表，O(N+M) 避免双重循环。 */
70	static HcclResult BuildSubTeamWorldMemberIds(
71	    HcommTeamHandle worldTeam, const uint32_t* subRankIds, uint32_t subRankNum, std::vector<uint32_t>& worldMemberIds)
72	{
73	    std::vector<uint32_t> worldRankIds = HcclTeamMgr::GetInstance().GetRankIds(worldTeam);
74	    CHK_PRT_RET(
75	        worldRankIds.empty(), HCCL_ERROR("[%s] GetRankIds failed, worldTeam[%p] not registered", __func__, worldTeam),
76	        HCCL_E_PARA);
77	    std::unordered_map<uint32_t, uint32_t> rankToMember;
78	    rankToMember.reserve(worldRankIds.size());
79	    for (uint32_t m = 0; m < worldRankIds.size(); m++) {
80	        rankToMember[worldRankIds[m]] = m;
81	    }
82	    worldMemberIds.resize(subRankNum);
83	    for (uint32_t i = 0; i < subRankNum; i++) {
84	        auto it = rankToMember.find(subRankIds[i]);
85	        CHK_PRT_RET(
86	            it == rankToMember.end(),
87	            HCCL_ERROR("[%s] subTeam rankId[%u] not in worldTeam rankIds", __func__, subRankIds[i]), HCCL_E_PARA);
88	        worldMemberIds[i] = it->second;
89	    }
90	    return HCCL_SUCCESS;
91	}
92	
93	/* 申请 syncMem 本地内存。失败时回滚已创建的 team（HcommTeamDestroy）。 */
94	static HcclResult AllocTeamSyncMem(HcommTeamHandle* team, uint64_t syncMemSize, void*& syncMemPtr)
95	{
96	    syncMemPtr = nullptr;
97	    HcclResult mallocRet = hrtMalloc(&syncMemPtr, syncMemSize);
98	    if (mallocRet != HCCL_SUCCESS || syncMemPtr == nullptr) {
99	        HCCL_ERROR("[AllocTeamSyncMem] hrtMalloc failed, ret[%d] size[%llu]", mallocRet, syncMemSize);
100	        (void)HcommTeamDestroy(*team);
101	        *team = nullptr;
102	        return HCCL_E_MEMORY;
103	    }
104	    return HCCL_SUCCESS;
105	}
106	
107	HcclResult HcclWorldTeamCreate(HcclComm comm, const HcclTeamCreateDesc* desc, HcommTeamHandle* worldTeam)
108	{
109	    CHK_PTR_NULL(comm);
110	    CHK_PTR_NULL(desc);
111	    CHK_PTR_NULL(worldTeam);
112	    CHK_PRT_RET(
113	        (desc->rankNum == 0 || desc->rankNum == 1),
114	        HCCL_ERROR("[%s] world team can not be empty or single rank", __func__), HCCL_E_PARA);
115	    CHK_PRT_RET(desc->rankIds == nullptr, HCCL_ERROR("[%s] rankIds is null", __func__), HCCL_E_PTR);
116	    CHK_PRT_RET(
117	        (desc->requirement.signalCount != 0 || desc->requirement.counterCount != 0),
118	        HCCL_ERROR(
119	            "[%s] signalCount[%u] and counterCount[%u] must be 0", __func__, desc->requirement.signalCount,
120	            desc->requirement.counterCount),
121	        HCCL_E_PARA);
122	    CHK_PRT_RET(
123	        desc->requirement.barrierCount == 0, HCCL_ERROR("[%s] barrierCount must be >= 1", __func__), HCCL_E_PARA);
124	
125	    auto* hcclComm = static_cast<hccl::hcclComm*>(comm);
126	    CollComm* collComm = hcclComm->GetCollComm();
127	    CHK_PTR_NULL(collComm);
128	    const std::string commId = collComm->GetCommId();
129	
130	    /* 0. 校验 desc 与通信域匹配（worldTeam 可为子集）。 */
131	    uint32_t commRankSize = collComm->GetRankSize();
132	    CHK_PRT_RET(
133	        desc->rankNum > commRankSize,
134	        HCCL_ERROR(
135	            "[%s] rankNum[%u] > commRankSize[%u], comm[%s]", __func__, desc->rankNum, commRankSize, commId.c_str()),
136	        HCCL_E_PARA);
137	
138	    /* 1. selfRankId 是本 rank 的实际 rankId，需在 rankIds 中查找其下标作为 memberId。 */
139	    uint32_t selfMemberId = 0;
140	    CHK_RET(FindSelfMemberId(desc, selfMemberId));
141	
142	    /* 2. 填充 HcommTeamCreateDesc，world team 无父 team，worldMemberIds 传 nullptr（L3 生成 [0,memberNum)）。 */
143	    HcommTeamCreateDesc hcommDesc = {};
144	    FillHcommTeamCreateDesc(desc, selfMemberId, nullptr, hcommDesc);
145	
146	    /* 3. 调用 Hcomm 层创建 world team，outSyncMemSize 为需要本地申请的 syncMem 字节数。 */
147	    uint64_t syncMemSize = 0;
148	    HcommResult ret = HcommTeamCreate(nullptr, &hcommDesc, worldTeam, &syncMemSize);
149	    CHK_PRT_RET(
150	        ret != 0 || *worldTeam == nullptr,
151	        HCCL_ERROR(
152	            "[%s] HcommTeamCreate failed, comm[%s] ret[%d] rankNum[%u] selfRankId[%u]", __func__, commId.c_str(), ret,
153	            desc->rankNum, desc->selfRankId),
154	        (ret != 0) ? static_cast<HcclResult>(ret) : HCCL_E_INTERNAL);
155	    CHK_PRT_RET(syncMemSize == 0, HCCL_ERROR("[%s] syncMemSize is 0", __func__), HCCL_E_PARA);
156	
157	    /* 4. 申请 syncMem 本地内存，后续基于 channel 交换。失败时回滚已创建的 team。 */
158	    void* syncMemPtr = nullptr;
159	    CHK_RET(AllocTeamSyncMem(worldTeam, syncMemSize, syncMemPtr));
160	
161	    /* 5. 注册 worldTeam 到 HcclTeamMgr（存 syncMem + collComm 反查 + rankIds），供 HcclSubTeamCreate/HcclTeamDestroy
162	     * 反查。 */
163	    HcclResult regRet = HcclTeamMgr::GetInstance().RegisterWorldTeam(
164	        *worldTeam, collComm, syncMemPtr, syncMemSize, desc->rankIds, desc->rankNum);
165	    if (regRet != HCCL_SUCCESS) {
166	        HCCL_ERROR("[%s] RegisterWorldTeam failed, comm[%s] ret[%d]", __func__, commId.c_str(), regRet);
167	        (void)hrtFree(syncMemPtr);
168	        (void)HcommTeamDestroy(*worldTeam);
169	        *worldTeam = nullptr;
170	        return regRet;
171	    }
172	
173	    HCCL_INFO(
174	        "[%s] success, team[%p] comm[%s] rankNum[%u] selfRankId[%u] selfMemberId[%u] syncMemSize[%llu]", __func__,
175	        *worldTeam, commId.c_str(), desc->rankNum, desc->selfRankId, selfMemberId, syncMemSize);
176	    return HCCL_SUCCESS;
177	}
178	
179	HcclResult HcclSubTeamCreate(HcommTeamHandle worldTeam, const HcclTeamCreateDesc* desc, HcommTeamHandle* team)
180	{
181	    CHK_PTR_NULL(worldTeam);
182	    CHK_PTR_NULL(desc);
183	    CHK_PTR_NULL(team);
184	
185	    CHK_PRT_RET(
186	        (desc->rankNum == 0 || desc->rankNum == 1),
187	        HCCL_ERROR("[%s] sub team can not be empty or single rank", __func__), HCCL_E_PARA);
188	    CHK_PRT_RET(desc->rankIds == nullptr, HCCL_ERROR("[%s] rankIds is null", __func__), HCCL_E_PTR);
189	    CHK_PRT_RET(
190	        (desc->requirement.signalCount != 0 || desc->requirement.counterCount != 0),
191	        HCCL_ERROR(
192	            "[%s] signalCount[%u] and counterCount[%u] must be 0", __func__, desc->requirement.signalCount,
193	            desc->requirement.counterCount),
194	        HCCL_E_PARA);
195	    CHK_PRT_RET(
196	        desc->requirement.barrierCount == 0, HCCL_ERROR("[%s] barrierCount must be >= 1", __func__), HCCL_E_PARA);
197	
198	    /* selfRankId 是本 rank 的实际 rankId，需在 rankIds 中查找其下标作为 memberId。 */
199	    uint32_t selfMemberId = 0;
200	    CHK_RET(FindSelfMemberId(desc, selfMemberId));
201	
202	    /* 1. 反查 subTeam 的 rankIds 在 worldTeam.rankIds 中的下标作为 worldMemberIds（worldTeam 的 memberId）。 */
203	    std::vector<uint32_t> worldMemberIds;
204	    CHK_RET(BuildSubTeamWorldMemberIds(worldTeam, desc->rankIds, desc->rankNum, worldMemberIds));
205	
206	    /* 2. 填充 HcommTeamCreateDesc：成员为 desc 的子集，父 team 为 worldTeam，worldMemberIds 用反查结果。 */
207	    HcommTeamCreateDesc hcommDesc = {};
208	    FillHcommTeamCreateDesc(desc, selfMemberId, worldMemberIds.data(), hcommDesc);
209	
210	    /* 3. 调用 Hcomm 层创建 sub team，outSyncMemSize 为需要本地申请的 syncMem 字节数。 */
211	    uint64_t syncMemSize = 0;
212	    HcommResult ret = HcommTeamCreate(worldTeam, &hcommDesc, team, &syncMemSize);
213	    CHK_PRT_RET(
214	        ret != 0 || *team == nullptr,
215	        HCCL_ERROR(
216	            "[%s] HcommTeamCreate failed, ret[%d] rankNum[%u] selfRankId[%u]", __func__, ret, desc->rankNum,
217	            desc->selfRankId),
218	        (ret != 0) ? static_cast<HcclResult>(ret) : HCCL_E_INTERNAL);
219	    CHK_PRT_RET(syncMemSize == 0, HCCL_ERROR("[%s] syncMemSize is 0", __func__), HCCL_E_PARA);
220	
221	    /* 4. 申请 syncMem 本地内存。失败时回滚已创建的 sub team。 */
222	    void* syncMemPtr = nullptr;
223	    CHK_RET(AllocTeamSyncMem(team, syncMemSize, syncMemPtr));
224	
225	    /* 5. 注册 sub team 到 HcclTeamMgr（建父子关系 + 存 syncMem + rankIds，collComm 取自 worldTeam 条目）。 */
226	    HcclResult regRet = HcclTeamMgr::GetInstance().RegisterSubTeam(
227	        worldTeam, *team, syncMemPtr, syncMemSize, desc->rankIds, desc->rankNum);
228	    if (regRet != HCCL_SUCCESS) {
229	        HCCL_ERROR("[%s] RegisterSubTeam failed, ret[%d]", __func__, regRet);
230	        (void)hrtFree(syncMemPtr);
231	        (void)HcommTeamDestroy(*team);
232	        *team = nullptr;
233	        return regRet;
234	    }
235	
236	    HCCL_INFO(
237	        "[%s] success, team[%p] worldTeam[%p] rankNum[%u] selfRankId[%u] selfMemberId[%u] syncMemSize[%llu]", __func__,
238	        *team, worldTeam, desc->rankNum, desc->selfRankId, selfMemberId, syncMemSize);
239	    return HCCL_SUCCESS;
240	}
