242	HcclResult HcclTeamDestroy(HcommTeamHandle team)
243	{
244	    CHK_PTR_NULL(team);
245	
246	    /* worldTeam 销毁时连带销毁其所有 subTeam 与 window（1:N），避免泄漏。subTeam 无子 team、无 window。 */
247	    if (HcclTeamMgr::GetInstance().FindWorldTeam(team) == team) {
248	        // 先销毁所有 subTeam（递归调 HcclTeamDestroy，subTeam 不会重复进入此分支）
249	        std::vector<HcommTeamHandle> subTeams = HcclTeamMgr::GetInstance().GetSubTeams(team);
250	        for (HcommTeamHandle sub : subTeams) {
251	            (void)HcclTeamDestroy(sub);
252	        }
253	        // 再销毁 worldTeam 拥有的 window
254	        std::vector<WindowInfo> windows = HcclTeamMgr::GetInstance().GetWorldTeamWindows(team);
255	        for (const auto& win : windows) {
256	            if (win.handle != nullptr) {
257	                (void)HcommTeamWindowDeregister(team, win.handle);
258	            }
259	        }
260	    }
261	
262	    /* 释放该 team 的 syncMem（hrtFree）+ erase 条目。 */
263	    HcclTeamMgr::GetInstance().UnregisterTeam(team);
264	
265	    HcommResult ret = HcommTeamDestroy(team);
266	    CHK_PRT_RET(
267	        ret != 0, HCCL_ERROR("[%s] HcommTeamDestroy failed, ret[%d]", __func__, ret), static_cast<HcclResult>(ret));
268	
269	    HCCL_INFO("[%s] success", __func__);
270	    return HCCL_SUCCESS;
271	}
