273	/* 注册 team 的 syncMem 内存（team 粒度，仅首次注册一次）。
274	 * syncMemHandle 已存在则跳过注册；syncMemHandle 出参返回当前句柄（首次或已存在），供调用方日志使用。 */
275	static HcclResult
276	RegisterTeamSyncMem(HcommTeamHandle team, const std::string& commId, CommMems* commMem, HcclMemHandle& syncMemHandle)
277	{
278	    syncMemHandle = HcclTeamMgr::GetInstance().GetTeamSyncMemHandle(team);
279	    if (syncMemHandle != nullptr) {
280	        HCCL_INFO(
281	            "[RegisterTeamSyncMem] syncMemHandle[%p] already registered, comm[%s] team[%p]", syncMemHandle,
282	            commId.c_str(), team);
283	        return HCCL_SUCCESS;
284	    }
285	    void* syncMemPtr = HcclTeamMgr::GetInstance().GetSyncMemPtr(team);
286	    uint64_t syncMemSize = HcclTeamMgr::GetInstance().GetSyncMemSize(team);
287	    if (syncMemPtr == nullptr || syncMemSize == 0) {
288	        HCCL_ERROR(
289	            "[RegisterTeamSyncMem] syncMemPtr[%p] or syncMemSize[%llu] is invalid, comm[%s] team[%p]", syncMemPtr,
290	            syncMemSize, commId.c_str(), team);
291	        return HCCL_E_INTERNAL;
292	    }
293	    CommMem syncMemVar{};
294	    syncMemVar.type = COMM_MEM_TYPE_DEVICE;
295	    syncMemVar.addr = syncMemPtr;
296	    syncMemVar.size = syncMemSize;
297	    std::ostringstream syncMemTagStream;
298	    syncMemTagStream << HCCL_TEAM_SYNCMEM_TAG_PREFIX << commId << "_team_" << team << "_addr_" << syncMemPtr << "_size_"
299	                     << syncMemSize;
300	    const std::string syncMemTagStr = syncMemTagStream.str();
301	    HcclResult ret = commMem->CommRegMem(syncMemTagStr, syncMemVar, &syncMemHandle);
302	    CHK_PRT_RET(
303	        ret != HCCL_SUCCESS,
304	        HCCL_ERROR(
305	            "[RegisterTeamSyncMem] register syncMem failed, comm[%s] ret[%d] size[%llu]", commId.c_str(), ret,
306	            syncMemSize),
307	        ret);
308	    HcclTeamMgr::GetInstance().SetTeamSyncMemHandle(team, syncMemHandle, syncMemTagStr);
309	    return HCCL_SUCCESS;
310	}
