329	/* 非复用路径：在 worldTeam 上创建业务 window，注册 localMem（失败回滚 window），记录到 worldTeam 的 window 列表。 */
330	static HcclResult CreateNewWindow(
331	    HcommTeamHandle worldTeam, const CommMem& localMem, const std::string& commId, CommMems* commMem,
332	    HcommWindowHandle* window)
333	{
334	    HcommResult hRet = HcommTeamWindowRegister(worldTeam, nullptr, window, HCOMM_TEAM_WINDOW_FLAG_SYMMETRIC);
335	    if (hRet != 0 || *window == nullptr) {
336	        HCCL_ERROR(
337	            "[CreateNewWindow] HcommTeamWindowRegister failed, comm[%s] worldTeam[%p] ret[%d]", commId.c_str(),
338	            worldTeam, hRet);
339	        *window = nullptr;
340	        return (hRet != 0) ? static_cast<HcclResult>(hRet) : HCCL_E_INTERNAL;
341	    }
342	    std::ostringstream userTagStream;
343	    userTagStream << HCCL_TEAM_USERMEM_TAG_PREFIX << commId << "_addr_" << localMem.addr << "_size_" << localMem.size;
344	    const std::string userTag = userTagStream.str();
345	    HcclMemHandle userHandle = nullptr;
346	    HcclResult ret = commMem->CommRegMem(userTag, localMem, &userHandle);
347	    if (ret != HCCL_SUCCESS) {
348	        HCCL_ERROR("[CreateNewWindow] register localMem failed, comm[%s] ret[%d]", commId.c_str(), ret);
349	        (void)HcommTeamWindowDeregister(worldTeam, *window);
350	        *window = nullptr;
351	        return ret;
352	    }
353	    HcclTeamMgr::GetInstance().AddWorldTeamWindow(worldTeam, *window, localMem, userHandle, userTag);
354	    return HCCL_SUCCESS;
355	}
