357	HcclResult HcclTeamWindowRegister(
358	    HcclComm comm, HcommTeamHandle worldTeam, const CommMem* localMem, HcommWindowHandle* window, uint32_t flag)
359	{
360	    CHK_PTR_NULL(comm);
361	    CHK_PTR_NULL(worldTeam);
362	    CHK_PTR_NULL(localMem);
363	    CHK_PTR_NULL(window);
364	    CHK_PRT_RET(flag != 0, HCCL_ERROR("[%s] flag[%u] is not supported, only support 0", __func__, flag), HCCL_E_PARA);
365	    CHK_PRT_RET(
366	        (localMem->type != COMM_MEM_TYPE_DEVICE),
367	        HCCL_ERROR("[%s] localMem type[%d] must be device", __func__, localMem->type), HCCL_E_PARA);
368	    CHK_PRT_RET(localMem->addr == nullptr, HCCL_ERROR("[%s] localMem addr is null", __func__), HCCL_E_PTR);
369	    CHK_PRT_RET(localMem->size == 0, HCCL_ERROR("[%s] localMem size is 0", __func__), HCCL_E_PARA);
370	
371	    auto* hcclComm = static_cast<hccl::hcclComm*>(comm);
372	    CollComm* collComm = hcclComm->GetCollComm();
373	    CHK_PTR_NULL(collComm);
374	    const std::string commId = collComm->GetCommId();
375	
376	    /* 入参 worldTeam 必须是 worldTeam（syncMem 注册已移至 ChannelsCreate，window 归 worldTeam 所有）。 */
377	    CHK_PRT_RET(
378	        HcclTeamMgr::GetInstance().FindWorldTeam(worldTeam) != worldTeam,
379	        HCCL_ERROR("[%s] worldTeam[%p] is not worldTeam", __func__, worldTeam), HCCL_E_PARA);
380	    CollComm* worldCollComm = HcclTeamMgr::GetInstance().FindCollComm(worldTeam);
381	    CHK_PTR_NULL(worldCollComm);
382	    CHK_PRT_RET(
383	        worldCollComm->GetCommId() != commId,
384	        HCCL_ERROR("[%s] worldTeam[%p] is not belong to comm[%s]", __func__, worldTeam, commId.c_str()), HCCL_E_PARA);
385	
386	    auto myRank = collComm->GetMyRank();
387	    CHK_PTR_NULL(myRank);
388	    CommMems* commMem = myRank->GetCommMems();
389	    CHK_PTR_NULL(commMem);
390	
391	    if (TryReuseWindow(worldTeam, *localMem, commId, worldTeam, window)) {
392	        return HCCL_SUCCESS;
393	    }
394	
395	    CHK_RET(CreateNewWindow(worldTeam, *localMem, commId, commMem, window));
396	
397	    HCCL_INFO("[%s] success, comm[%s] worldTeam[%p] window[%p]", __func__, commId.c_str(), worldTeam, *window);
398	    return HCCL_SUCCESS;
399	}
