401	HcclResult HcclTeamWindowDeregister(HcommTeamHandle team, HcommWindowHandle window)
402	{
403	    CHK_PTR_NULL(team);
404	    CHK_PTR_NULL(window);
405	
406	    /* 1. 取入参 team 对应的 worldTeam。 */
407	    HcommTeamHandle worldTeam = HcclTeamMgr::GetInstance().FindWorldTeam(team);
408	    CHK_PRT_RET(
409	        worldTeam == nullptr,
410	        HCCL_WARNING("[%s] FindWorldTeam failed, team[%p] not registered, maybe already destroyed", __func__, team),
411	        HCCL_SUCCESS);
412	
413	    /* 2. 从 worldTeam 的 window 列表移除该 window 的记录（WindowInfo）。
414	     *    注：不注销 localMem 的 MemReg（由通信域析构兜底清理）；不处理 syncMem（team 粒度，team 销毁时释放）。 */
415	    HcclTeamMgr::GetInstance().RemoveWorldTeamWindow(worldTeam, window);
416	
417	    /* 3. 销毁 Hcomm 层 window。 */
418	    HcommResult ret = HcommTeamWindowDeregister(worldTeam, window);
419	    CHK_PRT_RET(
420	        ret != 0, HCCL_ERROR("[%s] HcommTeamWindowDeregister failed, ret[%d]", __func__, ret),
421	        static_cast<HcclResult>(ret));
422	
423	    HCCL_INFO("[%s] success, team[%p] worldTeam[%p] window[%p]", __func__, team, worldTeam, window);
424	    return HCCL_SUCCESS;
425	}
