427	/* 查询本rank到peerRank的link，填充 HcclChannelDesc 的 endpoint/protocol 字段。*/
428	static HcclResult
429	FillChannelDescForPeer(HcclComm comm, HcommTeamHandle team, uint32_t selfRank, uint32_t peerRank, HcclChannelDesc& desc)
430	{
431	    uint32_t netLayer = 0;
432	    HcommResult hRet = HcommTeamGetNetLayer(team, &netLayer);
433	    CHK_PRT_RET(
434	        hRet != 0, HCCL_ERROR("[%s] HcommTeamGetNetLayer failed, ret[%d]", __func__, hRet),
435	        (hRet != 0) ? static_cast<HcclResult>(hRet) : HCCL_E_INTERNAL);
436	
437	    CommLink* links = nullptr;
438	    uint32_t linkNum = 0;
439	    HcclResult ret = HcclRankGraphGetLinks(comm, netLayer, selfRank, peerRank, &links, &linkNum);
440	    if (ret != HCCL_SUCCESS || links == nullptr || linkNum == 0) {
441	        HCCL_ERROR("[%s] no link found from rank[%u] to rank[%u]", __func__, selfRank, peerRank);
442	        return HCCL_E_NOT_FOUND;
443	    }
444	    const CommLink& link = links[0];
445	    desc.remoteRank = peerRank;
446	    desc.channelProtocol = link.linkAttr.linkProtocol;
447	    desc.localEndpoint = link.srcEndpointDesc;
448	    desc.remoteEndpoint = link.dstEndpointDesc;
449	    return HCCL_SUCCESS;
450	}
