452	/* 从 HcclTeamMgr 取 team 的 rankIds（memberId→rankId），推算 memberNum 与 selfMemberId。 */
453	static HcclResult GetTeamMemberInfo(HcommTeamHandle team, uint32_t selfRank, ChannelsCreateCtx& ctx)
454	{
455	    ctx.rankIds = HcclTeamMgr::GetInstance().GetRankIds(team);
456	    CHK_PRT_RET(
457	        ctx.rankIds.empty(), HCCL_ERROR("[%s] GetRankIds failed, team[%p] not registered", __func__, team),
458	        HCCL_E_PARA);
459	    ctx.memberNum = static_cast<uint32_t>(ctx.rankIds.size());
460	    bool selfFound = false;
461	    for (uint32_t m = 0; m < ctx.memberNum; m++) {
462	        if (ctx.rankIds[m] == selfRank) {
463	            ctx.selfMemberId = m;
464	            selfFound = true;
465	            break;
466	        }
467	    }
468	    CHK_PRT_RET(!selfFound, HCCL_ERROR("[%s] selfRank[%u] not in team rankIds", __func__, selfRank), HCCL_E_PARA);
469	    return HCCL_SUCCESS;
470	}
