472	/* 取 worldTeam 及其所有 window、memHandles；取 worldTeam 维度信息并计算 curToWorld 映射。 */
473	static HcclResult GetWorldTeamContext(HcommTeamHandle team, uint32_t selfRank, ChannelsCreateCtx& ctx)
474	{
475	    ctx.worldTeam = HcclTeamMgr::GetInstance().FindWorldTeam(team);
476	    CHK_PTR_NULL(ctx.worldTeam);
477	    ctx.windows = HcclTeamMgr::GetInstance().GetWorldTeamWindows(ctx.worldTeam); // 移动赋值，避免深拷贝
478	    ctx.syncMemTag = HcclTeamMgr::GetInstance().GetTeamSyncMemTag(team);
479	    // 只收集未交换的 memHandles（syncMemHandle + window localMemHandle），避免重复建链交换
480	    ctx.memHandles = HcclTeamMgr::GetInstance().CollectPendingMemHandles(ctx.worldTeam, team);
481	
482	    ctx.worldRankIds = HcclTeamMgr::GetInstance().GetRankIds(ctx.worldTeam);
483	    CHK_PRT_RET(
484	        ctx.worldRankIds.empty(),
485	        HCCL_ERROR("[%s] GetRankIds failed, worldTeam[%p] not registered", __func__, ctx.worldTeam), HCCL_E_PARA);
486	    ctx.worldMemberNum = static_cast<uint32_t>(ctx.worldRankIds.size());
487	    bool worldSelfFound = false;
488	    for (uint32_t w = 0; w < ctx.worldMemberNum; w++) {
489	        if (ctx.worldRankIds[w] == selfRank) {
490	            ctx.worldSelfMemberId = w;
491	            worldSelfFound = true;
492	            break;
493	        }
494	    }
495	    CHK_PRT_RET(
496	        !worldSelfFound, HCCL_ERROR("[%s] selfRank[%u] not in worldTeam rankIds", __func__, selfRank), HCCL_E_PARA);
497	    // curToWorld[m] = 当前 team memberId m 的 rankId 在 worldRankIds 中的下标（worldMemberId）
498	    ctx.curToWorld.assign(ctx.memberNum, 0);
499	    for (uint32_t m = 0; m < ctx.memberNum; m++) {
500	        uint32_t rankId = ctx.rankIds[m];
501	        for (uint32_t w = 0; w < ctx.worldMemberNum; w++) {
502	            if (ctx.worldRankIds[w] == rankId) {
503	                ctx.curToWorld[m] = w;
504	                break;
505	            }
506	        }
507	    }
508	    return HCCL_SUCCESS;
509	}
