511	/* 对每个 peer member 创建 channelCnt 个 channel，结果存 ctx.channelsByMember（self 为空）。 */
512	static HcclResult AcquireChannels(
513	    HcclComm comm, HcommTeamHandle team, const HcclTeamCreateChannelsDesc* desc, uint32_t selfRank,
514	    ChannelsCreateCtx& ctx)
515	{
516	    uint32_t channelCnt = desc->channelCnt;
517	    ctx.channelsByMember.assign(ctx.memberNum, {});
518	    for (uint32_t m = 0; m < ctx.memberNum; m++) {
519	        if (m == ctx.selfMemberId) {
520	            continue; // 本 member 不建到自己的 channel
521	        }
522	        uint32_t peerRank = ctx.rankIds[m];
523	        std::vector<HcclChannelDesc> channelDescs(channelCnt);
524	        HcclResult ret = HcclChannelDescInit(channelDescs.data(), channelCnt);
525	        CHK_PRT_RET(ret != HCCL_SUCCESS, HCCL_ERROR("[%s] HcclChannelDescInit failed, ret[%d]", __func__, ret), ret);
526	        for (uint32_t c = 0; c < channelCnt; c++) {
527	            ret = FillChannelDescForPeer(comm, team, selfRank, peerRank, channelDescs[c]);
528	            CHK_PRT_RET(
529	                ret != HCCL_SUCCESS,
530	                HCCL_ERROR("[%s] FillChannelDescForPeer failed, peerRank[%u] ret[%d]", __func__, peerRank, ret), ret);
531	            channelDescs[c].notifyNum = desc->notifyNum;
532	            if (!ctx.memHandles.empty()) {
533	                channelDescs[c].memHandles = ctx.memHandles.data();
534	                channelDescs[c].memHandleNum = static_cast<uint32_t>(ctx.memHandles.size());
535	            }
536	        }
537	        ctx.channelsByMember[m].assign(channelCnt, 0);
538	        ret = HcclChannelAcquire(comm, desc->engine, channelDescs.data(), channelCnt, ctx.channelsByMember[m].data());
539	        CHK_PRT_RET(
540	            ret != HCCL_SUCCESS,
541	            HCCL_ERROR(
542	                "[%s] HcclChannelAcquire failed, peerMember[%u] peerRank[%u] ret[%d]", __func__, m, peerRank, ret),
543	            ret);
544	    }
545	    return HCCL_SUCCESS;
546	}
