548	/* 构造 HcommTeamBindChannelsDesc，绑定 team 与 channel。 */
549	static HcclResult BindTeamChannels(
550	    HcommTeamHandle team, const HcclTeamCreateChannelsDesc* desc, const std::string& commId, ChannelsCreateCtx& ctx)
551	{
552	    std::vector<uint32_t> channelNumPerMember(ctx.memberNum, 0);
553	    std::vector<uint64_t*> channelsByMemberIdPtrs(ctx.memberNum, nullptr);
554	    // 保持各 member 的 channel 数组生命周期覆盖 BindChannels 调用
555	    for (uint32_t m = 0; m < ctx.memberNum; m++) {
556	        channelNumPerMember[m] = static_cast<uint32_t>(ctx.channelsByMember[m].size());
557	        channelsByMemberIdPtrs[m] = ctx.channelsByMember[m].data();
558	    }
559	    HcommTeamBindChannelsDesc bindDesc = {};
560	    (void)HcommTeamBindChannelsDescInit(&bindDesc);
561	    bindDesc.memberNum = ctx.memberNum;
562	    bindDesc.channelNumPerMember = channelNumPerMember.data();
563	    bindDesc.channelsByMemberId = channelsByMemberIdPtrs.data();
564	    HcommResult hRet = HcommTeamBindChannels(team, &bindDesc);
565	    CHK_PRT_RET(
566	        hRet != 0,
567	        HCCL_ERROR(
568	            "[%s] HcommTeamBindChannels failed, comm[%s] ret[%d] memberNum[%u]", __func__, commId.c_str(), hRet,
569	            ctx.memberNum),
570	        static_cast<HcclResult>(hRet));
571	    return HCCL_SUCCESS;
572	}
