574	/* 收集所有 peer channel 的远端内存+tag。selfMemberId 槽填本地 syncMem，peer 槽按 memberId 填远端 syncMem；
575	 * 各 window 的 localMem 远端按 (windowIndex, worldMemberId) 存 remoteMemsByWindow。 */
576	static HcclResult CollectRemoteMems(HcclComm comm, HcommTeamHandle team, ChannelsCreateCtx& ctx)
577	{
578	    ctx.syncMemRemoteMems.assign(ctx.memberNum, CommMem{});
579	    // selfMemberId 槽填本地 syncMem 内存
580	    void* localSyncMemPtr = HcclTeamMgr::GetInstance().GetSyncMemPtr(team);
581	    uint64_t localSyncMemSize = HcclTeamMgr::GetInstance().GetSyncMemSize(team);
582	    if (localSyncMemPtr != nullptr && localSyncMemSize > 0) {
583	        ctx.syncMemRemoteMems[ctx.selfMemberId].type = COMM_MEM_TYPE_DEVICE;
584	        ctx.syncMemRemoteMems[ctx.selfMemberId].addr = localSyncMemPtr;
585	        ctx.syncMemRemoteMems[ctx.selfMemberId].size = localSyncMemSize;
586	    }
587	    // window.mems 维度为 worldTeam memberNum，peer 槽按 worldMemberId 索引
588	    ctx.remoteMemsByWindow.assign(ctx.windows.size(), std::vector<CommMem>(ctx.worldMemberNum));
589	    for (uint32_t m = 0; m < ctx.memberNum; m++) {
590	        if (m == ctx.selfMemberId || ctx.channelsByMember[m].empty()) {
591	            continue;
592	        }
593	        uint32_t peerWorldMemberId = ctx.curToWorld[m];
594	        for (ChannelHandle channel : ctx.channelsByMember[m]) {
595	            if (channel == 0) {
596	                continue;
597	            }
598	            uint32_t memNum = 0;
599	            CommMem* remoteMems = nullptr;
600	            char** memTags = nullptr;
601	            HcclResult gRet = HcclChannelGetRemoteMems(comm, channel, &memNum, &remoteMems, &memTags);
602	            CHK_PRT_RET(
603	                gRet != HCCL_SUCCESS,
604	                HCCL_ERROR("[%s] HcclChannelGetRemoteMems failed, member[%u] ret[%d]", __func__, m, gRet), gRet);
605	            uint32_t userMemFilled = 0;
606	            for (uint32_t r = 0; r < memNum; r++) {
607	                std::string tag
608	                    = (memTags != nullptr && memTags[r] != nullptr) ? std::string(memTags[r]) : std::string();
609	                if (!ctx.syncMemTag.empty()
610	                    && tag.compare(0, strlen(HCCL_TEAM_SYNCMEM_TAG_PREFIX), HCCL_TEAM_SYNCMEM_TAG_PREFIX) == 0) {
611	                    ctx.syncMemRemoteMems[m] = remoteMems[r]; // 按下标 memberId 存
612	                    continue;
613	                }
614	                if (userMemFilled < ctx.windows.size()
615	                    && tag.compare(0, strlen(HCCL_TEAM_USERMEM_TAG_PREFIX), HCCL_TEAM_USERMEM_TAG_PREFIX) == 0) {
616	                    ctx.remoteMemsByWindow[userMemFilled][peerWorldMemberId] = remoteMems[r];
617	                    userMemFilled++;
618	                }
619	            }
620	        }
621	    }
622	    return HCCL_SUCCESS;
623	}
624	
625	/* per window 调 HcommTeamWindowBindRemoteMems（worldMemberId 维 mems）；调 HcommTeamBindRemoteSyncMem 绑定 syncMem。 */
626	static HcclResult BindWindowsAndSyncMem(HcommTeamHandle team, const std::string& commId, ChannelsCreateCtx& ctx)
627	{
628	    // 对每个 window 调 HcommTeamWindowBindRemoteMems
629	    for (size_t w = 0; w < ctx.windows.size(); w++) {
630	        std::vector<CommMem> windowMems(ctx.worldMemberNum);
631	        for (uint32_t m = 0; m < ctx.worldMemberNum; m++) {
632	            if (m == ctx.worldSelfMemberId) {
633	                continue;
634	            }
635	            windowMems[m] = ctx.remoteMemsByWindow[w][m];
636	        }
637	        // self 槽填调用者在 WindowRegister 时传入的本地内存（registeredLocalMem），与 peer 槽的远端 CommMem 对称
638	        windowMems[ctx.worldSelfMemberId] = ctx.windows[w].registeredLocalMem;
639	        HcommTeamWindowDesc winDesc = {};
640	        (void)HcommTeamWindowDescInit(&winDesc);
641	        winDesc.mems = windowMems.data();
642	        winDesc.memberNum = ctx.worldMemberNum;
643	        HcommResult bindWinRet = HcommTeamWindowBindRemoteMems(team, ctx.windows[w].handle, &winDesc);
644	        CHK_PRT_RET(
645	            bindWinRet != 0,
646	            HCCL_ERROR(
647	                "[%s] HcommTeamWindowBindRemoteMems failed, comm[%s] team[%p] window[%p] ret[%d]", __func__,
648	                commId.c_str(), team, ctx.windows[w].handle, bindWinRet),
649	            static_cast<HcclResult>(bindWinRet));
650	    }
651	    // 调 HcommTeamBindRemoteSyncMem
652	    HcommTeamBindSyncMemDesc syncDesc = {};
653	    (void)HcommTeamBindSyncMemDescInit(&syncDesc);
654	    syncDesc.remoteMems = ctx.syncMemRemoteMems.data();
655	    syncDesc.remoteMemNum = static_cast<uint32_t>(ctx.syncMemRemoteMems.size());
656	    HcommResult bindSyncRet = HcommTeamBindRemoteSyncMem(team, &syncDesc);
657	    CHK_PRT_RET(
658	        bindSyncRet != 0,
659	        HCCL_ERROR(
660	            "[%s] HcommTeamBindRemoteSyncMem failed, comm[%s] team[%p] ret[%d] remoteMemNum[%zu]", __func__,
661	            commId.c_str(), team, bindSyncRet, ctx.syncMemRemoteMems.size()),
662	        static_cast<HcclResult>(bindSyncRet));
663	    return HCCL_SUCCESS;
664	}
665	
666	HcclResult HcclTeamChannelsCreate(HcclComm comm, HcommTeamHandle team, const HcclTeamCreateChannelsDesc* desc)
667	{
668	    CHK_PTR_NULL(comm);
669	    CHK_PTR_NULL(team);
670	    CHK_PTR_NULL(desc);
671	    CHK_PRT_RET(desc->channelCnt == 0, HCCL_ERROR("[%s] channelCnt is 0", __func__), HCCL_E_PARA);
672	
673	    auto* hcclComm = static_cast<hccl::hcclComm*>(comm);
674	    CollComm* collComm = hcclComm->GetCollComm();
675	    CHK_PTR_NULL(collComm);
676	    const std::string commId = collComm->GetCommId();
677	    uint32_t selfRank = collComm->GetMyRankId();
678	
679	    CollComm* worldCollComm = HcclTeamMgr::GetInstance().FindCollComm(team);
680	    CHK_PTR_NULL(worldCollComm);
681	    CHK_PRT_RET(
682	        worldCollComm->GetCommId() != commId,
683	        HCCL_ERROR("[%s] team[%p] is not belong to comm[%s]", __func__, team, commId.c_str()), HCCL_E_PARA);
684	
685	    ChannelsCreateCtx ctx{};
686	    CHK_RET(GetTeamMemberInfo(team, selfRank, ctx));
687	
688	    /* 注册 team 的 syncMem 内存（team 粒度，仅首次注册一次），供 channel 交换与 GetWorldTeamContext 取用。 */
689	    auto myRank = collComm->GetMyRank();
690	    CHK_PTR_NULL(myRank);
691	    CommMems* commMem = myRank->GetCommMems();
692	    CHK_PTR_NULL(commMem);
693	    HcclMemHandle syncMemHandle = nullptr;
694	    CHK_RET(RegisterTeamSyncMem(team, commId, commMem, syncMemHandle));
695	
696	    CHK_RET(GetWorldTeamContext(team, selfRank, ctx));
697	    CHK_RET(AcquireChannels(comm, team, desc, selfRank, ctx));
698	    CHK_RET(BindTeamChannels(team, desc, commId, ctx));
699	    CHK_RET(CollectRemoteMems(comm, team, ctx));
700	    CHK_RET(BindWindowsAndSyncMem(team, commId, ctx));
701	
702	    HCCL_INFO(
703	        "[%s] success, comm[%s] team[%p] memberNum[%u] channelCnt[%u] windowNum[%zu] syncMemRemoteMemNum[%zu]",
704	        __func__, commId.c_str(), team, ctx.memberNum, desc->channelCnt, ctx.windows.size(),
705	        ctx.syncMemRemoteMems.size());
706	    return HCCL_SUCCESS;
707	}
