101	HcommResult HcommTeamMgr::AllocAndCopyWorldTeamIds(TeamEntry* entry, const uint32_t* src, uint32_t memberNum)
102	{
103	    // worldTeam（src==nullptr）：worldTeamIds 置为 [0,memberNum) 连续序列（memberId 自身）
104	    std::vector<uint32_t> sequentialIds;
105	    const uint32_t* srcPtr = src;
106	    if (src == nullptr) {
107	        sequentialIds.resize(memberNum);
108	        for (uint32_t i = 0; i < memberNum; i++) {
109	            sequentialIds[i] = i;
110	        }
111	        srcPtr = sequentialIds.data();
112	    }
113	
114	    void* devPtr = nullptr;
115	    HcommResult ret = static_cast<HcommResult>(hrtMalloc(&devPtr, static_cast<uint64_t>(memberNum * sizeof(uint32_t))));
116	    CHK_PRT_RET(ret != HCOMM_SUCCESS, HCCL_ERROR("[AllocAndCopyWorldTeamIds] hrtMalloc failed, ret[%d]", ret), ret);
117	
118	    ret = static_cast<HcommResult>(hrtMemSyncCopy(
119	        devPtr, static_cast<uint64_t>(memberNum * sizeof(uint32_t)), srcPtr,
120	        static_cast<uint64_t>(memberNum * sizeof(uint32_t)), HcclRtMemcpyKind::HCCL_RT_MEMCPY_KIND_HOST_TO_DEVICE));
121	    if (ret != HCOMM_SUCCESS) {
122	        HCCL_ERROR("[AllocAndCopyWorldTeamIds] hrtMemSyncCopy failed, ret[%d]", ret);
123	        (void)hrtFree(devPtr);
124	        return ret;
125	    }
126	
127	    entry->devWorldTeamIds = devPtr;
