129	
130	    entry->hostWorldTeamIds = static_cast<uint32_t*>(malloc(memberNum * sizeof(uint32_t)));
131	    if (entry->hostWorldTeamIds == nullptr) {
132	        HCCL_ERROR("[AllocAndCopyWorldTeamIds] malloc hostWorldTeamIds failed");
133	        (void)hrtFree(devPtr);
