139	        = memcpy_s(entry->hostWorldTeamIds, memberNum * sizeof(uint32_t), srcPtr, memberNum * sizeof(uint32_t));
140	    if (memRet != EOK) {
141	        HCCL_ERROR("[AllocAndCopyWorldTeamIds] memcpy_s hostWorldTeamIds failed, ret[%d]", memRet);
142	        free(entry->hostWorldTeamIds);
143	        entry->hostWorldTeamIds = nullptr;
144	        (void)hrtFree(devPtr);
145	        entry->devWorldTeamIds = nullptr;
146	        entry->hostTeam.worldTeamIds = nullptr;
147	        return HCOMM_E_MEMORY;
148	    }
149	
150	    return HCOMM_SUCCESS;
