153	HcommResult HcommTeamMgr::AllocChannelEntities(TeamEntry* entry)
154	{
155	    uint32_t memberNum = entry->hostTeam.memberNum;
156	    entry->hostChannelNums.resize(memberNum, 0);
157	    uint32_t totalChannels = 0;
158	    for (uint32_t i = 0; i < memberNum; i++) {
159	        uint32_t chNum = static_cast<uint32_t>(entry->channelsList[i].size());
160	        entry->hostChannelNums[i] = chNum;
161	        totalChannels += chNum;
162	    }
163	
164	    if (totalChannels == 0) {
165	        entry->devChannels = nullptr;
166	        entry->hostTeam.channelsBaseAddr = 0;
167	        return HCOMM_SUCCESS;
168	    }
169	
170	    void* devPtr = nullptr;
171	    HcommResult ret
172	        = static_cast<HcommResult>(hrtMalloc(&devPtr, static_cast<uint64_t>(totalChannels * sizeof(ChannelEntity))));
173	    CHK_PRT_RET(
174	        ret != HCOMM_SUCCESS,
175	        HCCL_ERROR("[AllocChannelEntities] hrtMalloc failed, totalChannels[%u] ret[%d]", totalChannels, ret), ret);
176	
177	    // 逐个 channel 做 D2D 拷贝：把 ChannelHandle 指向的 ChannelEntity 本体拷贝到连续内存对应偏移
178	    // 偏移按前缀和 sum(channelNumPerMember[0..peer-1]) + channelIdx 计算
179	    uint32_t offset = 0;
180	    for (uint32_t peer = 0; peer < memberNum; peer++) {
181	        for (uint32_t idx = 0; idx < entry->channelsList[peer].size(); idx++) {
182	            void* dst = reinterpret_cast<void*>(reinterpret_cast<uintptr_t>(devPtr) + offset * sizeof(ChannelEntity));
183	            void* src = reinterpret_cast<void*>(static_cast<uintptr_t>(entry->channelsList[peer][idx]));
184	            ret = static_cast<HcommResult>(hrtMemSyncCopy(
185	                dst, sizeof(ChannelEntity), src, sizeof(ChannelEntity),
186	                HcclRtMemcpyKind::HCCL_RT_MEMCPY_KIND_DEVICE_TO_DEVICE));
