406	void HcommTeamMgr::InitTeamEntry(TeamEntry* entry, const HcommTeamCreateDesc* desc, HcommTeamHandle worldTeam)
407	{
408	    entry->hostTeam.header.version = HCOMM_TEAM_VERSION;
409	    entry->hostTeam.header.magicWord = HCOMM_TEAM_MAGIC_WORD;
410	    entry->hostTeam.header.size = sizeof(HcommTeam);
411	    entry->hostTeam.header.reserved = 0;
412	    entry->hostTeam.memberNum = desc->memberNum;
413	    entry->hostTeam.selfMemberId = desc->selfMemberId;
414	    entry->hostTeam.netLayer = desc->netLayer;
415	    entry->hostTeam.engine = COMM_ENGINE_RESERVED;
416	    entry->syncMemReq = desc->requirement;
417	    entry->syncMemSize
418	        = static_cast<uint64_t>(
419	              desc->requirement.signalCount + desc->requirement.counterCount + desc->requirement.barrierCount)
420	          * sizeof(uint64_t) * desc->memberNum;
421	    entry->hostTeam.syncMem.syncMemReq = desc->requirement;
422	    entry->hostTeam.syncMem.syncMemSize = entry->syncMemSize;
423	
424	    if (worldTeam != nullptr) {
425	        entry->worldTeamHandle = worldTeam;
426	        entry->isSubTeam = true;
