470	    CHK_PRT_RET(ret != HCOMM_SUCCESS, HCCL_ERROR("[TeamCreate] ValidateSubTeam failed"), ret);
471	
472	    auto entry = std::make_unique<TeamEntry>();
473	    InitTeamEntry(entry.get(), desc, worldTeam);
474	
