{
    CHK_PRT_RET(
        (desc == nullptr || team == nullptr || outSyncMemSize == nullptr),
        HCCL_ERROR("[%s] nullptr parameter", __func__), HCOMM_E_PTR);
    CHK_PRT_RET(
